import type { CatalogueEntry } from "../../packages/core/src/index.js";

export const README_START =
  "<!-- checks:start (generated by pnpm gen:checks from the check registry) -->";
export const README_END = "<!-- checks:end -->";

const LEVEL = { high: "Fix this first", medium: "Fix soon", low: "Worth knowing" } as const;

/** The README's check list: one row per check, most urgent first, as the checks reference sorts them. */
export function renderChecksTable(entries: readonly CatalogueEntry[]): string {
  const rows = entries.map(
    (e) => `| \`${e.id}\` | ${LEVEL[e.severity]} | ${e.title.replace(/\|/g, "\\|")} |`,
  );
  return [
    `${entries.length} checks. Each one's what, why, fix and technical detail are in the [checks reference](https://github.com/alvinwquach/gaugeline/blob/main/docs/checks.md).`,
    "",
    "| Check | Level | What it catches |",
    "| ----- | ----- | --------------- |",
    ...rows,
  ].join("\n");
}

/** Replace what sits between the markers. Throws when a file has no markers, naming it. */
export function replaceChecksBlock(text: string, block: string, file: string): string {
  const start = text.indexOf(README_START);
  const end = text.indexOf(README_END);
  if (start < 0 || end < start)
    throw new Error(`${file} has no ${README_START} ... ${README_END} block.`);
  return `${text.slice(0, start + README_START.length)}\n\n${block}\n\n${text.slice(end)}`;
}
